.darma-loader-three-dots-collision{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 3.7);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-collision::before,
.darma-loader-three-dots-collision::after{
  content:"";
  position:absolute;
  top:0;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:inherit;
}
.darma-loader-three-dots-collision::before{left:calc(var(--td-gap) * -1);}
.darma-loader-three-dots-collision::after{left:var(--td-gap);}
.darma-loader-three-dots-collision::before{animation:darma-loader-three-dots-collision-td-collision-before var(--loader-speed, 0.6s) infinite ease-in-out;}
.darma-loader-three-dots-collision::after{animation:darma-loader-three-dots-collision-td-collision-after var(--loader-speed, 0.6s) infinite ease-in-out;}
@keyframes darma-loader-three-dots-collision-td-collision-before{
  0%,50%,100%{transform:translateX(0)}
  25%{transform:translateX(calc(var(--td-gap) * 0.72))}
}
@keyframes darma-loader-three-dots-collision-td-collision-after{
  0%,50%,100%{transform:translateX(0)}
  25%{transform:translateX(calc(var(--td-gap) * -0.72))}
}

